<?php
require_once __DIR__ . '/../includes/config.php';
if (session_status() === PHP_SESSION_NONE) session_start();
if (empty($_SESSION['admin_id']) && empty($_SESSION['admin_logged_in'])) { header('Location: admin-login.php'); exit; }
function h($v){ return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function tableExists($conn,$table){ $s=$conn->prepare("SELECT COUNT(*) c FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?"); if(!$s)return false; $s->bind_param('s',$table);$s->execute();$r=$s->get_result()->fetch_assoc();$s->close();return (int)($r['c']??0)>0; }
function colExists($conn,$table,$col){ $s=$conn->prepare("SELECT COUNT(*) c FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? AND COLUMN_NAME=?"); if(!$s)return false;$s->bind_param('ss',$table,$col);$s->execute();$r=$s->get_result()->fetch_assoc();$s->close();return (int)($r['c']??0)>0; }
$msg='';$err='';
$codReady=tableExists($conn,'rider_cod_settlements');
$paymentProof=colExists($conn,'payments','proof_image');

if($_SERVER['REQUEST_METHOD']==='POST'){
 $id=(int)($_POST['payment_id']??0);$action=$_POST['payment_action']??'';$type=$_POST['payment_type']??'online';
 if($id>0 && in_array($action,['approve','reject'],true)){
  $conn->begin_transaction();
  try{
   if($type==='cod'){
    if(!$codReady)throw new Exception('Rider COD table is not installed. Run database/payment_verification_upgrade.sql first.');
    $s=$conn->prepare("SELECT id,rider_id,amount,status FROM rider_cod_settlements WHERE id=? LIMIT 1 FOR UPDATE");$s->bind_param('i',$id);$s->execute();$p=$s->get_result()->fetch_assoc();$s->close();
    if(!$p)throw new Exception('COD payment record not found.');if($p['status']!=='pending')throw new Exception('This COD payment has already been processed.');
    $new=$action==='approve'?'approved':'rejected';$u=$conn->prepare("UPDATE rider_cod_settlements SET status=?,reviewed_at=NOW() WHERE id=? AND status='pending'");$u->bind_param('si',$new,$id);if(!$u->execute()||$u->affected_rows!==1)throw new Exception('COD payment could not be updated.');$u->close();
    if(tableExists($conn,'notifications')){ $title=$new==='approved'?'COD payment approved':'COD payment rejected';$message=$new==='approved'?'Your COD settlement of PKR '.number_format((float)$p['amount'],2).' has been approved by Admin.':'Your COD settlement of PKR '.number_format((float)$p['amount'],2).' was rejected by Admin.';$n=$conn->prepare("INSERT INTO notifications (user_id,role,title,message,type,reference_id,is_read) VALUES (?, 'rider', ?, ?, 'payment_update', ?, 0)");if($n){$rid=(int)$p['rider_id'];$n->bind_param('issi',$rid,$title,$message,$id);$n->execute();$n->close();}}
    $conn->commit();$msg=$new==='approved'?'Rider COD payment approved.':'Rider COD payment rejected.';
   }else{
    $s=$conn->prepare("SELECT p.id,p.order_id,p.status,p.payment_method,p.amount,o.user_id FROM payments p LEFT JOIN orders o ON o.id=p.order_id WHERE p.id=? LIMIT 1 FOR UPDATE");$s->bind_param('i',$id);$s->execute();$p=$s->get_result()->fetch_assoc();$s->close();if(!$p)throw new Exception('Online payment record not found.');if($p['status']!=='pending')throw new Exception('This payment has already been processed.');
    $new=$action==='approve'?'paid':'failed';$u=$conn->prepare("UPDATE payments SET status=?,paid_at=CASE WHEN ?='paid' THEN COALESCE(paid_at,CURRENT_TIMESTAMP) ELSE NULL END WHERE id=? AND status='pending'");$u->bind_param('ssi',$new,$new,$id);if(!$u->execute()||$u->affected_rows!==1)throw new Exception('Online payment could not be updated.');$u->close();
    if(tableExists($conn,'notifications')){$title=$new==='paid'?'Payment verified':'Payment rejected';$message=$new==='paid'?'Your online payment for order #'.$p['order_id'].' has been approved.':'Your online payment for order #'.$p['order_id'].' was rejected.';$n=$conn->prepare("INSERT INTO notifications (user_id,role,title,message,type,reference_id,is_read) VALUES (?, 'customer', ?, ?, 'payment_update', ?, 0)");if($n){$uid=(int)$p['user_id'];$oid=(int)$p['order_id'];$n->bind_param('issi',$uid,$title,$message,$oid);$n->execute();$n->close();}}
    $conn->commit();$msg=$new==='paid'?'Online payment approved.':'Online payment rejected.';
   }
  }catch(Throwable $e){$conn->rollback();$err=$e->getMessage();}
 }
}

$online=[];$cod=[];$onlineSummary=['pending'=>0,'paid'=>0,'failed'=>0];$codSummary=['pending'=>0,'approved'=>0,'rejected'=>0];
$q=$conn->query("SELECT p.id,p.order_id,p.payment_method,p.provider,p.status,p.amount,p.transaction_reference,p.created_at,o.order_number,u.full_name AS customer_name,u.phone AS customer_phone,r.name AS restaurant_name ".($paymentProof?',p.proof_image':'')." FROM payments p LEFT JOIN orders o ON o.id=p.order_id LEFT JOIN users u ON u.id=o.user_id LEFT JOIN restaurants r ON r.id=o.restaurant_id WHERE LOWER(COALESCE(p.payment_method,'')) NOT IN ('cash_on_delivery','cod','cash') ORDER BY p.created_at DESC");
if($q){while($r=$q->fetch_assoc()){$online[]=$r;if(isset($onlineSummary[$r['status']]))$onlineSummary[$r['status']]++;}}else{$err='Unable to load online payments: '.$conn->error;}
if($codReady){$q=$conn->query("SELECT c.*,r.full_name AS rider_name,r.phone AS rider_phone FROM rider_cod_settlements c LEFT JOIN riders r ON r.id=c.rider_id ORDER BY c.created_at DESC");if($q){while($r=$q->fetch_assoc()){$cod[]=$r;if(isset($codSummary[$r['status']]))$codSummary[$r['status']]++;}}}
function proofUrl($path){$path=trim((string)$path);if($path==='')return '';if(preg_match('~^https?://~i',$path))return $path;return '../'.ltrim($path,'/');}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payment Verification - Humsafar</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><style>*{box-sizing:border-box}body{margin:0;background:#fff8fb;font-family:Segoe UI,Arial;color:#292929}.page{margin-left:218px;padding:28px}.wrap{max-width:1350px;margin:auto}.head{background:#fff;border:1px solid #f0dce5;border-radius:15px;padding:18px;display:flex;justify-content:space-between;align-items:center}.head h1{margin:0;font-size:26px}.sub{margin:5px 0 0;color:#888;font-size:11px}.brand{color:#ed0038;font-weight:800;font-size:11px}.tabs{display:flex;gap:8px;margin:18px 0}.tab{border:1px solid #efdce4;background:#fff;padding:10px 16px;border-radius:9px;font-size:11px;font-weight:800;cursor:pointer}.tab.active{background:#ed0038;color:#fff;border-color:#ed0038}.panel{display:none}.panel.active{display:block}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:13px;margin-bottom:15px}.stat{background:#fff;border:1px solid #f0dce5;border-radius:13px;padding:15px}.num{font-size:23px;font-weight:900}.label{font-size:10px;color:#888;font-weight:700}.tablebox{background:#fff;border:1px solid #f0dce5;border-radius:14px;overflow:auto}table{width:100%;border-collapse:collapse;min-width:1050px}th,td{padding:12px;border-bottom:1px solid #f3e6eb;text-align:left;font-size:11px}th{background:#fff5f8;color:#777;font-size:9px;text-transform:uppercase}small{color:#999}.badge{padding:5px 8px;border-radius:20px;font-size:9px;font-weight:800}.pending{background:#fff4d8;color:#916500}.paid,.approved{background:#e7f8ed;color:#18733b}.failed,.rejected{background:#ffe9ed;color:#a4002b}.actions{display:flex;gap:5px}.btn{border:0;border-radius:7px;padding:7px 9px;font-size:9px;font-weight:800;cursor:pointer}.approve{background:#e7f8ed;color:#18733b}.reject{background:#ffe9ed;color:#a4002b}.view{background:#f2eafb;color:#6d3aa8}.msg{padding:11px;border-radius:8px;margin:15px 0;font-size:11px;font-weight:700;background:#e7f8ed;color:#176c36}.err{background:#fff0f3;color:#a0002d}.empty{padding:35px;text-align:center;color:#999}.modal{display:none;position:fixed;inset:0;background:rgba(0,0,0,.72);z-index:9999;align-items:center;justify-content:center;padding:25px}.modal.open{display:flex}.modalbox{background:#fff;border-radius:14px;max-width:850px;max-height:90vh;padding:15px;position:relative}.modalbox img{display:block;max-width:100%;max-height:78vh;object-fit:contain}.close{position:absolute;right:8px;top:8px;width:32px;height:32px;border:0;border-radius:50%;background:#ed0038;color:#fff;cursor:pointer}.missing{color:#999;font-size:10px}.notice{padding:12px;background:#fff5d9;border:1px solid #f2df9d;border-radius:9px;color:#775900;font-size:10px;margin-bottom:14px}@media(max-width:900px){.page{margin-left:0}.stats{grid-template-columns:1fr}.head{display:block}.brand{display:block;margin-top:9px}}</style></head><body><?php include __DIR__.'/admin-sidebar.php';?><main class="page"><div class="wrap"><div class="head"><div><h1>Payment Verification</h1><p class="sub">Verify customer online payments and rider COD settlements from one place.</p></div><div class="brand"><i class="fa-solid fa-shield-halved"></i> HUMSAFAR ADMIN</div></div><?php if($msg):?><div class="msg"><i class="fa-solid fa-circle-check"></i> <?=h($msg)?></div><?php endif;?><?php if($err):?><div class="msg err"><i class="fa-solid fa-circle-exclamation"></i> <?=h($err)?></div><?php endif;?><div class="tabs"><button class="tab active" onclick="showTab('online',this)"><i class="fa-solid fa-credit-card"></i> Customer Online Payments</button><button class="tab" onclick="showTab('cod',this)"><i class="fa-solid fa-motorcycle"></i> Rider COD Payments</button></div><section id="online" class="panel active"><div class="stats"><div class="stat"><div class="num"><?=$onlineSummary['pending']?></div><div class="label">Pending Online Verification</div></div><div class="stat"><div class="num"><?=$onlineSummary['paid']?></div><div class="label">Approved Online Payments</div></div><div class="stat"><div class="num"><?=$onlineSummary['failed']?></div><div class="label">Rejected Online Payments</div></div></div><div class="tablebox"><table><thead><tr><th>Order</th><th>Customer</th><th>Restaurant</th><th>Method</th><th>Amount</th><th>Reference</th><th>Proof</th><th>Status</th><th>Action</th></tr></thead><tbody><?php if(!$online):?><tr><td colspan="9" class="empty">No customer online payments found.</td></tr><?php else:foreach($online as $r):$proof=proofUrl($r['proof_image']??'');?><tr><td><b>#<?=h($r['order_number']?:$r['order_id'])?></b></td><td><?=h($r['customer_name'])?><br><small><?=h($r['customer_phone'])?></small></td><td><?=h($r['restaurant_name'])?></td><td><?=h(strtoupper($r['payment_method']))?></td><td><b>PKR <?=number_format((float)$r['amount'],2)?></b></td><td><?=h($r['transaction_reference']?:'—')?></td><td><?php if($proof):?><button type="button" class="btn view" onclick="openProof(<?=json_encode($proof)?>)"><i class="fa-solid fa-image"></i> View</button><?php else:?><span class="missing">No screenshot</span><?php endif;?></td><td><span class="badge <?=h($r['status'])?>"><?=h(ucfirst($r['status']))?></span></td><td><?php if($r['status']==='pending'):?><div class="actions"><form method="post"><input type="hidden" name="payment_id" value="<?=h($r['id'])?>"><input type="hidden" name="payment_type" value="online"><button class="btn approve" name="payment_action" value="approve"><i class="fa-solid fa-check"></i> Approve</button></form><form method="post"><input type="hidden" name="payment_id" value="<?=h($r['id'])?>"><input type="hidden" name="payment_type" value="online"><button class="btn reject" name="payment_action" value="reject"><i class="fa-solid fa-xmark"></i> Reject</button></form></div><?php else:?>—<?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></section><section id="cod" class="panel"><div class="stats"><div class="stat"><div class="num"><?=$codSummary['pending']?></div><div class="label">Pending Rider COD Verification</div></div><div class="stat"><div class="num"><?=$codSummary['approved']?></div><div class="label">Approved COD Settlements</div></div><div class="stat"><div class="num"><?=$codSummary['rejected']?></div><div class="label">Rejected COD Settlements</div></div></div><?php if(!$codReady):?><div class="notice"><i class="fa-solid fa-triangle-exclamation"></i> Rider COD verification is ready in this page, but the database table is not installed yet. Run <b>database/payment_verification_upgrade.sql</b> once in phpMyAdmin.</div><?php endif;?><div class="tablebox"><table><thead><tr><th>Rider</th><th>Amount</th><th>Method</th><th>Reference</th><th>Payment Proof</th><th>Status</th><th>Date</th><th>Action</th></tr></thead><tbody><?php if(!$codReady||!$cod):?><tr><td colspan="8" class="empty">No rider COD settlement records found.</td></tr><?php else:foreach($cod as $r):$proof=proofUrl($r['proof_image']??'');?><tr><td><b><?=h($r['rider_name']?:'Rider #'.$r['rider_id'])?></b><br><small><?=h($r['rider_phone'])?></small></td><td><b>PKR <?=number_format((float)$r['amount'],2)?></b></td><td><?=h($r['payment_method'])?></td><td><?=h($r['transaction_reference']?:'—')?></td><td><?php if($proof):?><button type="button" class="btn view" onclick="openProof(<?=json_encode($proof)?>)"><i class="fa-solid fa-image"></i> View</button><?php else:?><span class="missing">No screenshot</span><?php endif;?></td><td><span class="badge <?=h($r['status'])?>"><?=h(ucfirst($r['status']))?></span></td><td><?=h($r['created_at'])?></td><td><?php if($r['status']==='pending'):?><div class="actions"><form method="post"><input type="hidden" name="payment_id" value="<?=h($r['id'])?>"><input type="hidden" name="payment_type" value="cod"><button class="btn approve" name="payment_action" value="approve"><i class="fa-solid fa-check"></i> Approve</button></form><form method="post"><input type="hidden" name="payment_id" value="<?=h($r['id'])?>"><input type="hidden" name="payment_type" value="cod"><button class="btn reject" name="payment_action" value="reject"><i class="fa-solid fa-xmark"></i> Reject</button></form></div><?php else:?>—<?php endif;?></td></tr><?php endforeach;endif;?></tbody></table></div></section></div></main><div class="modal" id="proofModal" onclick="if(event.target===this)closeProof()"><div class="modalbox"><button class="close" onclick="closeProof()"><i class="fa-solid fa-xmark"></i></button><img id="proofImage" src="" alt="Payment screenshot"></div></div><script>function showTab(id,btn){document.querySelectorAll('.panel').forEach(function(x){x.classList.remove('active')});document.querySelectorAll('.tab').forEach(function(x){x.classList.remove('active')});document.getElementById(id).classList.add('active');btn.classList.add('active');}function openProof(src){document.getElementById('proofImage').src=src;document.getElementById('proofModal').classList.add('open');}function closeProof(){document.getElementById('proofModal').classList.remove('open');document.getElementById('proofImage').src='';}</script></body></html>